/* From Uiverse.io by sans-script - Tags: checkbox, square */
.__UIV_SCOPE__ .center {
  width: 100%;
  text-align: center;
}

.__UIV_SCOPE__ input[type="checkbox"] {
  position: relative;
  top: 8px;
  width: 40px;
  height: 40px;
  -webkit-appearance: none;
  outline: none;
  transition: 0.5s;
}

.__UIV_SCOPE__ input[type="checkbox"]:before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 4px solid #262626;
  box-sizing: border-box;
  transition: 0.5s;
}

.__UIV_SCOPE__ input:checked[type="checkbox"]:before {
  border-left: none;
  border-top: none;
  width: 20px;
  border-color: rgb(24, 196, 24);
  transform: rotate(45deg) translate(5px, -10px);
}
